{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        # In practice test cases satisfy constraints; but handle gracefully
        pass
    allocations = [s['minimum'] for s in segments]
    remaining = budget - sum(allocations)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                score = s['importance'] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
}
